 bad=copy.deepcopy(a);bad['text']=bad['text'].replace('ﬁ','fi');assert bad['text']!=a['text'];negatives.append({'case':'ASCII_expansion_cannot_claim_exact_source_Unicode_body','blocked':not same_occurrence(pair,b,bad)})
